pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token contract that records transferFrom calls
        TokenMock token = new TokenMock();
        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);
        uint[] memory vals = new uint[](2);
        vals[0] = 100;
        vals[1] = 200;
        bool success;
        try c.transfer(address(this), address(token), tos, vals) {
            success = true;
        } catch {
            success = false;
        }
        // Reference: token.transferFrom called 2 times (i=0 and i=1)
        // Bug: called only 1 time (i=0 only)
        // So after call, token's callCount should be 2 for reference, 1 for bug
        // We assert that callCount == 2, which passes on reference but fails on bug
        assertTrue(token.callCount() == 2);
    }
}

contract TokenMock {
    uint public callCount;
    function transferFrom(address, address, uint) external returns (bool) {
        callCount++;
        return true;
    }
}

