pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = makeAddr("alice");
        address bob = makeAddr("bob");
        // Avoid collision with existing test helper
        address recipient = address(0x1234);

        vm.deal(address(c), 3 wei);
        address[] memory tos = new address[](3);
        tos[0] = alice;
        tos[1] = bob;
        tos[2] = alice;
        uint[] memory vals = new uint[](3);
        vals[0] = 1;
        vals[1] = 1;
        vals[2] = 1;

        // We need a target that logs calls; use a contract that increments a counter
        // Actually simpler: the mutant skips the second call, so one wei remains in the contract
        // But require uses transferFrom which we can't directly observe. 
        // Use the fact that the contract's own balance after the call differs.
        // The reference will call transferFrom on all three, moving all 3 wei out.
        // The mutant skips the second, moving only 2 wei out, leaving 1 wei.
        // However transferFrom may fail if the target doesn't implement it. 
        // We need a target that accepts the call.
        // Use a simple contract that just does nothing on transferFrom.
        // But we can't define another contract. Instead, use address(this) which has fallback.

        // Redo: make the target address(this), which has a receive and fallback
        vm.deal(alice, 0);
        vm.deal(address(this), 0);
        vm.deal(address(c), 0);

        // Actually: the contract calls caddress.call(...) with transferFrom selector.
        // If caddress doesn't implement transferFrom, the call succeeds but does nothing.
        // Then balance doesn't change. The difference is in the number of calls made.
        // We need to track calls externally.
        // Use a self-destructing contract: deploy a helper that increments a counter on each call
        // But we can't deploy another contract.
        // 
        // Simpler: use the fact that each call to transferFrom with value 0 succeeds.
        // The reference makes 3 calls, the mutant makes 2. But both return true.
        // No observable difference unless the target reverts on the second call.
        // 
        // Instead, make the second call revert. In reference, the second call reverts => loop continues
        // In mutant, the second is skipped => only two calls, both succeed => return true.
        // So reference returns true? Actually the reference's loop continues even if a call reverts,
        // because it doesn't check the result. Both return true always.
        //
        // Key: caddress is a parameter, so we can pass a contract that records calls.
        // But we can't import another contract. Use address(this) with a fallback that reverts on even calls.
        revert("Need a counter contract");
    }
}

