pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a recipient contract that records calls
        Recorder rec = new Recorder();
        address[] memory tos = new address[](2);
        tos[0] = address(rec);
        tos[1] = address(rec);
        uint[] memory vals = new uint[](2);
        vals[0] = 1;
        vals[1] = 1;
        c.transfer(address(0), address(rec), tos, vals);
        // Reference contract calls transferFrom twice, so rec.totalCalls() will be 2
        // Mutant with i+=2 skips second element, so rec.totalCalls() will be 1
        assertTrue(rec.totalCalls() == 2);
    }
}

contract Recorder {
    uint public totalCalls;
    function transferFrom(address, address, uint) external returns (bool) {
        totalCalls++;
        return true;
    }
    fallback() external { }
}

