pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // We need a token contract that implements transferFrom to test the difference.
        // Deploy a minimal ERC20-like token that tracks balances.
        Token token = new Token();
        // Setup: give from and this contract some tokens
        address from = address(0x1234);
        token.mint(from, 100);
        token.mint(address(this), 50);
        // Give token approval from the from address
        vm.prank(from);
        token.approve(address(c), 100);

        // Prepare arrays for the call
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        uint[] memory amounts = new uint[](1);
        amounts[0] = 10;

        // Record balances before
        uint balanceFromBefore = token.balanceOf(from);
        uint balanceContractBefore = token.balanceOf(address(this));

        // Call the transfer function
        c.transfer(from, address(token), tos, amounts);

        // Check balance changes: in reference, from loses 10, contract unchanged.
        uint balanceFromAfter = token.balanceOf(from);
        uint balanceContractAfter = token.balanceOf(address(this));

        // Reference: from == 90, contract == 50; Bug: from == 100, contract == 40
        // We assert that from's balance decreased (reference behavior)
        assertTrue(balanceFromAfter < balanceFromBefore, "from balance should decrease");
    }
}

contract Token {
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;

    function mint(address to, uint amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
